import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Mail, Lock, User as UserIcon, ArrowRight, ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { loginUser, registerUser } from "@/lib/auth";
import logo from "@/assets/logo.png";

const AuthGate = () => {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [mode, setMode] = useState<"login" | "register">("login");
  
  // Login form state
  const [loginEmail, setLoginEmail] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [loginLoading, setLoginLoading] = useState(false);
  
  // Register form state
  const [registerName, setRegisterName] = useState("");
  const [registerContact, setRegisterContact] = useState("");
  const [registerPassword, setRegisterPassword] = useState("");
  const [registerLoading, setRegisterLoading] = useState(false);
  const [registerType, setRegisterType] = useState<"email" | "phone">("email");

  const canLogin = loginEmail.trim().includes("@") && loginPassword.trim().length >= 6;
  const canRegister = registerName.trim().length >= 2 && registerContact.trim().length >= 5 && registerPassword.trim().length >= 6;

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canLogin) return;
    
    setLoginLoading(true);
    try {
      const user = await loginUser({ contact: loginEmail.trim(), password: loginPassword.trim() });
      toast({
        title: "Успешный вход",
        description: "Добро пожаловать в OxusEdu.com!",
      });
      navigate("/dashboard");
    } catch (err) {
      toast({
        title: "Ошибка входа",
        description: "Неверный email или пароль",
        variant: "destructive",
      });
    } finally {
      setLoginLoading(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canRegister) return;
    
    setRegisterLoading(true);
    try {
      const user = await registerUser({
        name: registerName.trim(),
        contact: registerContact.trim(),
        password: registerPassword.trim(),
        userType: "school",
        legalAcceptedAt: new Date().toISOString(),
      });
      toast({
        title: "Аккаунт создан",
        description: "Добро пожаловать в OxusEdu.com!",
      });
      navigate("/dashboard");
    } catch (err) {
      toast({
        title: "Ошибка регистрации",
        description: "Не удалось создать аккаунт",
        variant: "destructive",
      });
    } finally {
      setRegisterLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 bg-gradient-to-br from-background via-background/95 to-background">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="text-center mb-8">
          <img src={logo} alt="OxusEdu.com" className="h-12 w-auto mx-auto mb-4" />
          <h1 className="text-2xl font-heading font-bold text-foreground mb-2">
            {mode === "login" ? "Вход в аккаунт" : "Создать аккаунт"}
          </h1>
          <p className="text-muted-foreground">
            {mode === "login" ? "Добро пожаловать обратно!" : "Начните свой путь к успеху"}
          </p>
        </div>

        {/* Mode Toggle */}
        <div className="flex rounded-lg bg-muted p-1 mb-6">
          <button
            onClick={() => setMode("login")}
            className={`flex-1 rounded-md py-2 px-3 text-sm font-medium transition-all ${
              mode === "login"
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            Вход
          </button>
          <button
            onClick={() => setMode("register")}
            className={`flex-1 rounded-md py-2 px-3 text-sm font-medium transition-all ${
              mode === "register"
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            Регистрация
          </button>
        </div>

        {/* Forms */}
        <div className="p-6 rounded-2xl bg-card border border-border/50 shadow-card">
          {mode === "login" ? (
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="login-email">Email</Label>
                <div className="relative">
                  <Mail className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="login-email"
                    type="email"
                    placeholder="your@email.com"
                    value={loginEmail}
                    onChange={(e) => setLoginEmail(e.target.value)}
                    className="pl-10"
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="login-password">Пароль</Label>
                <div className="relative">
                  <Lock className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="login-password"
                    type="password"
                    placeholder="••••••••"
                    value={loginPassword}
                    onChange={(e) => setLoginPassword(e.target.value)}
                    className="pl-10"
                    required
                  />
                </div>
              </div>

              <Button
                type="submit"
                disabled={!canLogin || loginLoading}
                className="w-full"
              >
                {loginLoading ? "Вход..." : "Войти"}
              </Button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="register-name">Имя</Label>
                <div className="relative">
                  <UserIcon className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="register-name"
                    placeholder="Например, Дмитрий"
                    value={registerName}
                    onChange={(e) => setRegisterName(e.target.value)}
                    className="pl-10"
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="register-contact">Email или телефон</Label>
                <div className="relative">
                  {registerType === "email" ? (
                    <Mail className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  ) : (
                    <UserIcon className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  )}
                  <Input
                    id="register-contact"
                    type={registerType}
                    placeholder={registerType === "email" ? "your@email.com" : "+7 (999) 999-99-99"}
                    value={registerContact}
                    onChange={(e) => setRegisterContact(e.target.value)}
                    className="pl-10"
                    required
                  />
                </div>
                <div className="flex gap-2 mt-1">
                  <button
                    type="button"
                    onClick={() => setRegisterType("email")}
                    className={`text-xs px-2 py-1 rounded ${
                      registerType === "email"
                        ? "bg-primary text-primary-foreground"
                        : "text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    Email
                  </button>
                  <button
                    type="button"
                    onClick={() => setRegisterType("phone")}
                    className={`text-xs px-2 py-1 rounded ${
                      registerType === "phone"
                        ? "bg-primary text-primary-foreground"
                        : "text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    Телефон
                  </button>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="register-password">Пароль</Label>
                <div className="relative">
                  <Lock className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="register-password"
                    type="password"
                    placeholder="••••••••"
                    value={registerPassword}
                    onChange={(e) => setRegisterPassword(e.target.value)}
                    className="pl-10"
                    required
                  />
                </div>
              </div>

              <Button
                type="submit"
                disabled={!canRegister || registerLoading}
                className="w-full"
              >
                {registerLoading ? "Создание..." : "Создать аккаунт"}
              </Button>
            </form>
          )}
        </div>

        {/* Back to Home */}
        <div className="mt-6 text-center">
          <button
            onClick={() => navigate("/")}
            className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors text-sm"
          >
            <ArrowLeft className="w-4 h-4" />
            На главную
          </button>
        </div>
      </div>
    </div>
  );
};

export default AuthGate;
