import { createRoot } from "react-dom/client";
import App from "./App.tsx";
import "./index.css";

// Error boundary for mobile devices
window.addEventListener('error', (event) => {
  console.error('Global error caught:', event.error);
  // Try to clear problematic data
  try {
    const keys = Object.keys(localStorage);
    const authKeys = keys.filter(key => key.includes('aa_'));
    authKeys.forEach(key => localStorage.removeItem(key));
  } catch (e) {
    console.warn('Could not clear localStorage on error:', e);
  }
});

window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled promise rejection:', event.reason);
});

// Initialize auth without top-level await
const initializeAuth = async () => {
  try {
    // Add timeout to prevent hanging
    const timeoutPromise = new Promise((_, reject) => 
      setTimeout(() => reject(new Error('Auth initialization timeout')), 3000)
    );
    
    const authPromise = import("./lib/auth.ts").then(({ initAuthListener }) => {
      initAuthListener();
    });
    
    await Promise.race([authPromise, timeoutPromise]);
    console.log('Auth initialized successfully');
  } catch (error) {
    console.error('Failed to initialize auth:', error);
    // Continue without auth - app should still work
  }
};

// Make sure DOM is ready
const initializeApp = () => {
  const rootElement = document.getElementById("root");
  if (!rootElement) {
    console.error('Root element not found, retrying...');
    setTimeout(initializeApp, 100);
    return;
  }

  try {
    const root = createRoot(rootElement);
    root.render(<App />);
    console.log('App rendered successfully');
    
    // Initialize auth after render
    initializeAuth();
  } catch (error) {
    console.error('Failed to render app:', error);
    
    // Fallback: show error message
    rootElement.innerHTML = `
      <div style="display: flex; align-items: center; justify-content: center; min-height: 100vh; font-family: system-ui; text-align: center; padding: 20px;">
        <div>
          <h1>Application Error</h1>
          <p>Please refresh the page</p>
          <button onclick="window.location.reload()" style="padding: 10px 20px; background: #007bff; color: white; border: none; border-radius: 5px; cursor: pointer;">
            Refresh
          </button>
        </div>
      </div>
    `;
  }
};

// Start initialization when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeApp);
} else {
  initializeApp();
}
