import { Search, Filter, BookOpen, Clock, DollarSign, Users, Star, ChevronDown, X, Award } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface Course {
  id: string;
  title: string;
  provider: string;
  category: string;
  level: string;
  duration: string;
  price: string;
  rating: number;
  students: number;
  description: string;
  skills: string[];
  certificate: boolean;
  language: string;
}

